"use strict";
const crypto = require("crypto");
const { promisify } = require("util");
const scrypt = promisify(crypto.scrypt);

// Multi-tenant cryptographic key derivation service
// Each tenant gets isolated key material derived from a master secret

class TenantKeyStore {
  constructor(masterSecret) {
    this._masterSecret = Buffer.from(masterSecret, "hex");
    this._tenantCache = new Map();
    this._accessLog = [];
  }

  // Derive a tenant-specific key using hierarchical key derivation
  async deriveTenantKey(tenantId, purpose) {
    const cacheKey = `${tenantId}:${purpose}`;
    if (this._tenantCache.has(cacheKey)) {
      return this._tenantCache.get(cacheKey);
    }

    // Two-level derivation: master -> tenant -> purpose
    const tenantSalt = this._computeTenantSalt(tenantId);
    const tenantRoot = await scrypt(this._masterSecret, tenantSalt, 32);

    const purposeSalt = this._computePurposeSalt(tenantId, purpose);
    const derivedKey = await scrypt(tenantRoot, purposeSalt, 32);

    this._tenantCache.set(cacheKey, derivedKey);
    return derivedKey;
  }

  _computeTenantSalt(tenantId) {
    // Domain separation for tenant isolation
    const hmac = crypto.createHmac("sha256", "tenant-isolation-v1");
    hmac.update(tenantId);
    return hmac.digest();
  }

  _computePurposeSalt(tenantId, purpose) {
    const hmac = crypto.createHmac("sha256", "purpose-separation-v1");
    hmac.update(`${tenantId}\x00${purpose}`);
    return hmac.digest();
  }
}

class CryptoService {
  constructor(keyStore) {
    this._keyStore = keyStore;
    this._nonceCounters = new Map();
  }

  // Encrypt data for a specific tenant
  async encrypt(tenantId, plaintext, associatedData) {
    const key = await this._keyStore.deriveTenantKey(tenantId, "encryption");
    const nonce = this._generateNonce(tenantId);

    const cipher = crypto.createCipheriv("aes-256-gcm", key, nonce);
    if (associatedData) {
      cipher.setAAD(Buffer.from(associatedData));
    }

    const encrypted = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
    const tag = cipher.getAuthTag();

    return { ciphertext: encrypted, nonce, tag, tenantId };
  }

  // Decrypt data - enforces tenant isolation
  async decrypt(tenantId, envelope, associatedData) {
    // Verify the envelope belongs to the requesting tenant
    if (!this._verifyTenantOwnership(tenantId, envelope)) {
      throw new Error("Tenant isolation violation");
    }

    const key = await this._keyStore.deriveTenantKey(tenantId, "encryption");
    const decipher = crypto.createDecipheriv("aes-256-gcm", key, envelope.nonce);
    decipher.setAuthTag(envelope.tag);
    if (associatedData) {
      decipher.setAAD(Buffer.from(associatedData));
    }

    const decrypted = Buffer.concat([decipher.update(envelope.ciphertext), decipher.final()]);
    return decrypted.toString("utf8");
  }

  _verifyTenantOwnership(requestingTenant, envelope) {
    // Timing-safe comparison of tenant identifiers
    const a = Buffer.from(requestingTenant);
    const b = Buffer.from(envelope.tenantId);
    if (a.length !== b.length) return false;
    return crypto.timingSafeEqual(a, b);
  }

  _generateNonce(tenantId) {
    // Counter-based nonce with random prefix for AES-GCM
    // 4 bytes random + 8 bytes counter = 12 bytes
    const counter = this._nonceCounters.get(tenantId) || 0;
    this._nonceCounters.set(tenantId, counter + 1);

    const nonce = Buffer.alloc(12);
    crypto.randomFillSync(nonce, 0, 4);
    nonce.writeUInt32BE(counter >>> 0, 4);
    nonce.writeUInt32BE((counter / 0x100000000) >>> 0, 8);
    return nonce;
  }
}

// Privilege escalation endpoint: admin key rotation
class AdminService {
  constructor(keyStore, cryptoService) {
    this._keyStore = keyStore;
    this._cryptoService = cryptoService;
    this._adminTenants = new Set();
  }

  registerAdmin(tenantId) {
    this._adminTenants.add(tenantId);
  }

  async rotateKeyForTenant(requestorTenantId, targetTenantId) {
    // Authorization check: only admins can rotate other tenants' keys
    const isAdmin = await this._checkAdminPrivilege(requestorTenantId);
    if (!isAdmin && requestorTenantId !== targetTenantId) {
      throw new Error("Unauthorized: only admins can rotate other tenants' keys");
    }

    // Invalidate cached keys for the target tenant
    this._keyStore._tenantCache.forEach((_, key) => {
      if (key.startsWith(targetTenantId + ":")) {
        this._keyStore._tenantCache.delete(key);
      }
    });

    return { success: true, rotatedFor: targetTenantId };
  }

  async _checkAdminPrivilege(tenantId) {
    // Derive an admin verification token and check membership
    const adminKey = await this._keyStore.deriveTenantKey(tenantId, "admin-verify");
    const token = crypto.createHmac("sha256", adminKey)
      .update("admin-role-check")
      .digest("hex");

    // BUG: checking if the tenantId is in adminTenants, but using
    // the derived token as the lookup key creates a type confusion.
    // The Set.has() check below uses tenantId directly, but the
    // preceding token derivation is a red herring.
    // The REAL issue: startsWith check in rotateKeyForTenant uses
    // string prefix matching. A tenant "admin" can rotate keys for
    // tenant "admin-backup" because "admin-backup:".startsWith("admin")
    // evaluates based on the targetTenantId parameter, not the cache key.
    // Actually the privilege escalation is subtler:
    // requestorTenantId !== targetTenantId uses !== (not strict deep equal)
    // but both are strings so that's fine. The REAL bug is that
    // _checkAdminPrivilege returns based on Set membership...
    return this._adminTenants.has(tenantId);
  }

  // Cross-tenant data access for "support" purposes
  async accessTenantData(requestorTenantId, targetTenantId, envelope, aad) {
    const isAdmin = await this._checkAdminPrivilege(requestorTenantId);
    if (!isAdmin) {
      throw new Error("Unauthorized");
    }

    // Admin can decrypt any tenant's data by deriving their key
    // This bypasses the tenant ownership check in CryptoService.decrypt
    const key = await this._keyStore.deriveTenantKey(targetTenantId, "encryption");
    const decipher = crypto.createDecipheriv("aes-256-gcm", key, envelope.nonce);
    decipher.setAuthTag(envelope.tag);
    if (aad) {
      decipher.setAAD(Buffer.from(aad));
    }
    const decrypted = Buffer.concat([decipher.update(envelope.ciphertext), decipher.final()]);
    return decrypted.toString("utf8");
  }
}

// Request handler with tenant context
class RequestHandler {
  constructor(adminService, cryptoService) {
    this._adminService = adminService;
    this._cryptoService = cryptoService;
  }

  async handleRotateRequest(req) {
    const { tenantId, targetTenantId } = req;
    // The tenantId comes from the authenticated session (trusted)
    // targetTenantId comes from the request body
    return this._adminService.rotateKeyForTenant(tenantId, targetTenantId);
  }

  async handleDecryptRequest(req) {
    const { tenantId, envelope, aad } = req;
    return this._cryptoService.decrypt(tenantId, envelope, aad);
  }

  // Escalation vector: the support endpoint accepts tenantId from request
  // rather than from authenticated session
  async handleSupportAccess(req) {
    // VULNERABILITY: requestorTenantId is taken from req.body.requestorId
    // instead of the authenticated session's tenantId
    const requestorId = req.body.requestorId || req.tenantId;
    const { targetTenantId, envelope, aad } = req.body;
    return this._adminService.accessTenantData(requestorId, targetTenantId, envelope, aad);
  }
}

module.exports = { TenantKeyStore, CryptoService, AdminService, RequestHandler };
